from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M16','Classificazione e validazione','Geometria dei modelli, probabilità e trasferibilità delle prestazioni')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M16',i,b)
def flow(i,labs):
 b=''
 for k,lab in enumerate(labs):
  y=.4+1.85*k;b+=rect(.5,y,6.9,y+1.15,'Classical' if k%2==0 else 'Quantum')+n(3.7,y+.575,lab,w=6,size=11.5)
  if k<len(labs)-1:b+=a(3.7,y+1.3,3.7,y+1.68)
 return d(i,b)
m.sezione_nuova('Campione e domanda predittiva')
p('Classificare campioni entro un dominio definito',
'''La classificazione associa un insieme di misure a una classe, utilizzando esempi nei quali la risposta è già disponibile. Il dataset didattico contiene centottanta campioni sintetici, raccolti idealmente in diciotto stazioni e suddivisi fra Arenaria, Basalto e Calcare. Quattro variabili composizionali e la densità costituiscono i predittori. Le etichette e la separazione fra gruppi derivano dal generatore della simulazione, per cui le prestazioni misurano il comportamento entro questo esercizio e richiedono nuove evidenze prima di un impiego su campioni reali.''',figura='M16/F01',didascalia='Vista di due predittori fra i cinque disponibili. I simboli distinguono campioni di addestramento e di test.',richiamo='La domanda predittiva comprende le classi, le misure disponibili e la popolazione di applicazione.',origine='M16:1–15')
p('Rischio predittivo e distribuzione di applicazione',
'''Una regola appresa viene valutata mediante la perdita su nuovi casi della popolazione di interesse. Con perdita zero–uno, il rischio corrisponde alla probabilità di classificazione errata. La media degli errori sul test è una stima riferita alla distribuzione rappresentata da quei dati, la cui pertinenza dipende dal modo in cui sono stati raccolti e separati. Cambiamenti di strumento, ambiente o classi possono richiedere una nuova valutazione.''',formula=r'R(f)=E\!\left[\mathbf1\{f(X)\ne Y\}\right]\\\widehat R_{test}=\frac1{n_{test}}\sum_i\mathbf1\{f(x_i)\ne y_i\}',destra='La prestazione sul campione utilizzato per adattare il modello risponde a una domanda diversa dalla prestazione su nuove stazioni. Quando più provini appartengono alla stessa stazione, la loro dipendenza deve entrare sia nel disegno di validazione sia nella quantificazione dell’incertezza.',richiamo='La validità della valutazione dipende dalla corrispondenza fra test e contesto di applicazione.',origine='M16:1–10,106–110; approfondimento R5')
p('Provini e stazioni come livelli del campionamento',
'''L’identificativo è unico per ogni provino, mentre il codice di stazione compare dieci volte perché descrive il raggruppamento delle misure. Questa ripetizione conserva informazione sul disegno di raccolta. Una separazione casuale delle righe potrebbe distribuire provini della stessa stazione fra addestramento e test, favorendo una valutazione legata a condizioni locali già osservate. Per esaminare il trasferimento a stazioni ulteriori, tutti i provini di una stazione vengono assegnati allo stesso insieme.''',tikz=d('D01',rect(.5,.6,6.9,1.7)+n(3.7,1.15,'Una stazione: condizioni condivise',w=6)+a(1.7,1.9,1.7,3)+a(3.7,1.9,3.7,3)+a(5.7,1.9,5.7,3)+''.join(rect(x,3.2,x+1.6,4.5)+n(x+.8,3.85,lab,w=1.4,size=11) for x,lab in [(.9,'Provino A'),(2.9,'Provino B'),(4.9,'Provino C')])+n(3.7,5.5,'Il gruppo resta unito nella validazione.',w=6.7)),richiamo='L’unità di separazione deve riflettere l’unità sulla quale si vuole valutare la generalizzazione.',origine='M16:11–20')
c=estratto('M16','split',"d <- read.csv('dati/ml_v3.csv')\ntr <- d$split=='train'; te <- !tr\nstopifnot(!anyDuplicated(d$id),\n sum(tr)==150,sum(te)==30,\n length(intersect(d$stazione[tr],\n d$stazione[te]))==0)\ntable(d$litologia,d$split)")
p('La separazione prestabilita per stazioni',
'''Le stazioni con suffisso sei costituiscono il test, mentre le altre cinque stazioni di ciascuna classe alimentano l’addestramento. Si ottengono centocinquanta campioni in quindici stazioni e trenta campioni in tre stazioni, con dieci osservazioni per classe nel test. Il controllo verifica disgiunzione e conteggi senza estrarre una nuova divisione a ogni esecuzione. La presenza di una sola stazione di test per classe limita l’informazione sulla variabilità fra stazioni, anche quando tutti i provini vengono classificati correttamente.''',codice=c,richiamo='I trenta provini di test appartengono a tre stazioni e conservano questa struttura nella lettura delle prestazioni.',origine='M16:16–20')
m.sezione_nuova('Trasformazioni e geometria della decisione')
p('Una regola di riferimento prima dei modelli',
'''La classe più frequente nell’addestramento fornisce una regola elementare con cui confrontare il valore aggiunto dei predittori. Poiché le tre classi hanno cinquanta campioni ciascuna, il laboratorio risolve il pareggio mediante l’ordine alfabetico e assegna Arenaria a tutti i casi. Nel test bilanciato la regola ottiene dieci classificazioni corrette su trenta, pari a un terzo. Anche questo riferimento viene definito utilizzando soltanto l’addestramento, affinché il confronto rispetti il medesimo protocollo dei modelli più articolati.''',formula=r'\widehat y=\arg\max_c n_{c,train},\qquad Acc_{test}=\frac{10}{30}',tikz=flow('D02',['Frequenze nel solo addestramento','Regola dichiarata per il pareggio','Predizione costante: Arenaria']),richiamo='Il riferimento rende interpretabile il miglioramento ottenuto mediante le variabili predittive.',origine='M16:21–25')
p('Una scala comune stimata sull’addestramento',
'''La standardizzazione sottrae la media e divide per la deviazione standard di ciascun predittore, entrambe stimate sull’addestramento. Gli stessi parametri vengono applicati ai campioni di test, che mantengono così il sistema di riferimento nel quale è stato adattato il modello. Le medie standardizzate del test possono essere diverse da zero, poiché descrivono osservazioni ulteriori. Una trasformazione calcolata separatamente sul test cambierebbe le coordinate ricevute dal classificatore e utilizzerebbe informazioni esterne al procedimento definito.''',formula=r'z_{ij}=\frac{x_{ij}-\overline x_{j,train}}{s_{j,train}},\qquad s_{j,train}>0',figura='M16/F02',didascalia='Medie dei predittori standardizzati. Il riferimento dell’addestramento viene conservato nel test.',richiamo='I parametri di ogni trasformazione appresa seguono il medesimo confine dei dati usati per adattare il modello.',origine='M16:26–30')
c=estratto('M16','scaling',"d <- read.csv('dati/ml_v3.csv')\nf <- c('SiO2','CaO','MgO','FeO','densita')\nX <- as.matrix(d[f]); tr <- d$split=='train'\nmu <- colMeans(X[tr,])\ns <- apply(X[tr,],2,sd)\nstopifnot(all(s>0))\nA <- scale(X[tr,],mu,s)\nB <- scale(X[!tr,],mu,s)\nstopifnot(max(abs(colMeans(A)))<1e-12)\ncolMeans(B)")
p('La trasformazione come oggetto da conservare',
'''Il codice separa la stima dei parametri dalla loro applicazione, rendendo ispezionabili media e deviazione standard. Questi oggetti devono essere conservati insieme al classificatore per trasformare ogni nuovo campione nello stesso modo. Il controllo della deviazione standard intercetta predittori costanti, per i quali la divisione sarebbe indefinita. L’esecuzione su una sessione pulita verifica inoltre che la trasformazione utilizzi i dati dichiarati e non valori rimasti nell’ambiente da un’analisi precedente.''',codice=c,richiamo='Il modello distribuito comprende anche le trasformazioni necessarie a interpretarne gli input.',origine='M16:26–30')
p('Il classificatore del centroide più vicino',
'''Ogni classe è rappresentata dalla media dei suoi predittori standardizzati. Un nuovo campione viene assegnato al centroide con minima distanza euclidea, secondo una regola di pareggio dichiarata. Il metodo favorisce classi compatte e ben descritte dal proprio centro, mentre gruppi multimodali o con dispersioni molto differenti possono richiedere una rappresentazione più articolata. La scelta della scala determina il contributo delle variabili alla distanza e appartiene quindi alla definizione del classificatore.''',formula=r'c_k=\frac1{n_k}\sum_{i:y_i=k}z_i,\qquad\widehat y(z)=\arg\min_k\|z-c_k\|^2',tikz=d('D03',r'\fill[Classical] (1.3,2.1) circle (4pt);\fill[Quantum] (5.8,2.1) circle (4pt);\fill[Measure] (3.5,4.6) circle (4pt);'+linea(1.3,2.1,3.5,4.6,'Classical')+linea(5.8,2.1,3.5,4.6,'Quantum')+n(1.3,1.1,r'$c_1$',size=16)+n(5.8,1.1,r'$c_2$',size=16)+n(3.5,5.5,r'Nuovo campione $z$',w=5)+n(3.5,.25,'Confronto delle distanze',w=6,size=11)),richiamo='La decisione dipende dalla rappresentazione delle classi e dalla metrica utilizzata.',origine='M16:31–35')
p('Regioni di decisione in due dimensioni',
'''La figura adatta un classificatore distinto utilizzando soltanto silice e densità standardizzate, così da mostrare le regioni assegnate ai tre centroidi. Le frontiere separano punti equidistanti da due centri e risultano rette nella metrica euclidea. Le croci indicano i centroidi stimati, mentre i punti rappresentano l’addestramento. Questa vista illustra la geometria bidimensionale; le prestazioni riportate per il modello principale derivano invece dalle cinque variabili dichiarate e non possono essere lette direttamente da queste sole coordinate.''',formula=r'2z^\top(c_2-c_1)=\|c_2\|^2-\|c_1\|^2',figura='M16/F05',didascalia='Regioni del classificatore a due predittori. Le croci indicano i centri; i colori identificano le classi sintetiche.',richiamo='Una proiezione o un modello ridotto deve essere distinto dal classificatore usato nella valutazione completa.',origine='M16:31–35; approfondimento R5')
p('Vicini prossimi e voto locale',
'''Il metodo dei k vicini assegna la classe mediante il voto dei campioni più prossimi nella metrica prescelta. Un valore piccolo di k descrive variazioni locali fini, mentre un valore maggiore amplia il vicinato e modifica il compromesso fra flessibilità e stabilità. Le regole sui pareggi possono incidere sul risultato: class::knn include per impostazione predefinita le distanze pari a quella del k-esimo vicino e risolve casualmente i pareggi di voto. Seme e convenzioni vengono pertanto registrati nel codice.''',formula=r'\widehat y(z)=\arg\max_c\sum_{i\in N_k(z)}\mathbf1\{y_i=c\}',tikz=d('D04',r'\draw[Quantum,dashed,line width=.8pt] (3.7,3) ellipse [x radius=1.8cm,y radius=2.069cm];\fill[Measure] (3.7,3) circle (4pt);'+''.join(rf'\fill[{co}] ({x},{y}) circle (3pt);' for x,y,co in [(2.5,2.5,'Classical'),(3.2,1.5,'Classical'),(4.8,3.6,'Quantum'),(5.8,1.5,'Quantum'),(1.2,4.8,'Classical')])+n(3.7,.4,'Tre vicini nella regione illustrata',w=6.7,size=11)+n(3.7,5.8,'Il voto dipende da distanza e numero di vicini.',w=6.8,size=11)),richiamo='Numero di vicini, scala e gestione dei pareggi definiscono insieme la regola di classificazione.',fonti='R, class: knn',origine='M16:36–40')
m.sezione_nuova('Selezione e validazione per gruppi')
p('Ogni partizione ripete l’intera procedura',
'''La validazione interna divide le quindici stazioni di addestramento in cinque partizioni, ciascuna delle quali esclude una stazione per classe. In ogni passaggio si ristimano media e deviazione standard sulle dodici stazioni rimaste, si adatta il classificatore e si predicono le tre stazioni escluse. Il test esterno resta fuori da queste operazioni. Calcolare la standardizzazione una sola volta su tutto l’addestramento trasferirebbe nel modello informazioni della partizione che dovrebbe essere esclusa.''',tikz=flow('D05',['12 stazioni: trasformazione e adattamento','3 stazioni: previsione e perdita','Ripetizione per cinque partizioni']),richiamo='La validazione valuta una procedura completa, comprese le trasformazioni stimate dai dati.',origine='M16:56–60')
p('Selezione di k e regola per i pareggi',
'''I valori uno, tre, sette e quindici vengono confrontati sulle stesse cinque partizioni per stazioni. In questo dataset tutti ottengono accuratezza media pari a uno, per cui la regola prestabilita seleziona il primo valore della lista. Il pareggio rivela che l’esempio distingue poco le alternative e impedisce di attribuire superiorità sostanziale al valore scelto. Le prestazioni utilizzate per selezionare un parametro restano risultati di selezione; una valutazione conclusiva richiede dati esterni al processo decisionale oppure una validazione annidata.''',formula=r'\widehat k=\arg\max_{k\in\{1,3,7,15\}}\frac15\sum_{v=1}^{5}Acc_v(k)',figura='M16/F03',didascalia='Tutti i valori di k raggiungono accuratezza uno nelle cinque partizioni. Il primo valore risolve il pareggio dichiarato.',richiamo='L’uguaglianza delle prestazioni limita le conclusioni comparative consentite dal dataset.',origine='M16:61–65')
p('Separare esplorazione e valutazione conclusiva',
'''Le esercitazioni confrontano più metodi e riutilizzano le etichette di test per chiarirne il funzionamento. Il loro insieme costituisce un percorso didattico esplorativo, del quale sarebbe improprio presentare il migliore risultato come valutazione finale indipendente. In un progetto applicato, scelte di variabili, trasformazioni, parametri e soglie vengono fissate prima di consultare il test conclusivo. Se i risultati del test inducono nuove modifiche, quella porzione di dati entra nel processo di sviluppo e occorre una verifica ulteriore.''',tikz=d('D06',rect(.5,.4,6.9,1.6)+n(3.7,1,'Sviluppo e selezione interna',w=6)+a(3.7,1.8,3.7,2.4)+linea(.5,2.7,6.9,2.7,'Measure')+n(3.7,3.2,'Scelte fissate',w=6,color='Measure')+a(3.7,3.7,3.7,4.3)+rect(.5,4.5,6.9,5.7,'Quantum')+n(3.7,5.1,'Valutazione su dati ulteriori',w=6)),richiamo='La storia delle decisioni determina il ruolo effettivo dei dati nella valutazione.',origine='M16:36–40,61–65,106–110')
m.sezione_nuova('Alberi e insiemi di classificatori')
p('Partizioni ricorsive e impurità di un nodo',
'''Un albero suddivide lo spazio dei predittori mediante condizioni successive e assegna una classe nelle regioni terminali. L’impurità di Gini misura la mescolanza delle classi in un nodo; una separazione viene valutata attraverso la riduzione dell’impurità, ponderando i nodi figli per la loro numerosità. Le soglie apprese mantengono le unità originali. Nel laboratorio la profondità massima è tre, con parametri di crescita espliciti e senza attribuire alle soglie una validità petrografica universale.''',formula=r'G(t)=1-\sum_c p_{c|t}^2\\\Delta G=G(t)-\frac{n_L}{n_t}G(L)-\frac{n_R}{n_t}G(R)',tikz=d('D07',rect(1.8,.4,5.6,1.6)+n(3.7,1,r'$x_j\leq c$',size=17)+a(2.7,1.8,1.8,3)+a(4.7,1.8,5.6,3,'Quantum')+rect(.5,3.2,3.2,4.7)+rect(4.2,3.2,6.9,4.7,'Quantum')+n(1.85,3.95,'Nodo L',w=2.3)+n(5.55,3.95,'Nodo R',w=2.3)+n(3.7,5.6,'Soglia appresa, unità originali.',w=6.5,size=11)),richiamo='Una soglia appresa descrive la partizione del modello entro il campione e il protocollo utilizzati.',fonti='R, rpart: parametri di controllo',origine='M16:46–50')
p('Complessità e prestazioni su stazioni escluse',
'''Aumentando la profondità da uno a due, l’albero passa da circa due terzi a uno di accuratezza sull’addestramento, mentre la validazione per stazioni raggiunge circa 0,993. Le profondità ulteriori mantengono questi valori nel caso didattico. La figura documenta una separazione molto agevole fra le classi sintetiche e non mostra un peggioramento progressivo della validazione. Il principio generale resta quello di confrontare l’adattamento con prestazioni esterne all’adattamento, evitando di dedurre la generalizzazione dalla sola riuscita sul campione utilizzato.''',figura='M16/F09',didascalia='Stessi controlli di crescita, profondità diverse. La CV esclude intere stazioni e viene ricalcolata per ogni profondità.',richiamo='La complessità va giudicata attraverso una validazione pertinente, anche quando un esempio produce curve quasi coincidenti.',origine='M16:51–55')
p('Foreste casuali e aggregazione dei voti',
'''Una foresta combina alberi ottenuti introducendo casualità nei campioni e nelle variabili candidate alle suddivisioni. L’aggregazione dei voti può stabilizzare la previsione quando gli errori dei singoli alberi presentano diversità sufficiente. Il laboratorio usa ottanta alberi e due variabili candidate per nodo. Il risultato corretto su tutti i trenta campioni di test riguarda il dataset sintetico e il confronto esplorativo del corso; il numero di alberi non compensa una validazione inadeguata o un cambiamento del dominio di applicazione.''',formula=r'\widehat y(x)=\arg\max_c\sum_{b=1}^{B}\mathbf1\{h_b(x)=c\}',tikz=d('D08',''.join(rect(x,.8,x+1.7,2.2,col)+n(x+.85,1.5,lab,w=1.5,size=11)+a(x+.85,2.4,3.7,3.7,col) for x,lab,col in [(.4,'Albero 1','Classical'),(2.85,'Albero 2','Quantum'),(5.3,'Albero B','Measure')])+rect(1,3.9,6.4,5.3)+n(3.7,4.6,'Voto aggregato',w=5)),richiamo='L’aggregazione modifica la regola predittiva e conserva la necessità di verificare il dominio della previsione.',fonti='Breiman, 2001: Random Forests',origine='M16:66–70')
m.sezione_nuova('Metriche e probabilità')
p('La matrice di confusione conserva i conteggi',
'''Le righe identificano le classi osservate e le colonne quelle previste, mantenendo lo stesso ordine su entrambi gli assi. I valori diagonali contano le classificazioni corrette, mentre le celle esterne mostrano quali classi vengano confuse. Per il centroide a cinque predittori, tutti i trenta campioni sono classificati correttamente, con dieci casi in ciascuna cella diagonale. Il risultato deve essere letto insieme alla facilità del dataset, al numero limitato di stazioni e alla natura esplorativa del riuso del test.''',formula=r'C_{ab}=\sum_i\mathbf1\{y_i=a,\widehat y_i=b\},\qquad Acc=\frac{\operatorname{tr}(C)}{n}',figura='M16/F04',didascalia='Are. = Arenaria; Bas. = Basalto; Calc. = Calcare. Centroide adattato sui cinque predittori standardizzati.',richiamo='I conteggi e le unità di validazione devono accompagnare qualsiasi percentuale di accuratezza.',origine='M16:71–75')
p('Precisione e richiamo usano denominatori diversi',
'''Definita Basalto come classe positiva, i veri positivi sono i basalti previsti correttamente; i falsi positivi provengono dalle altre classi, mentre i falsi negativi sono basalti assegnati altrove. La precisione considera l’insieme dei positivi previsti e il richiamo quello dei positivi osservati. Nel caso del centroide entrambi valgono uno, poiché si contano dieci veri positivi e nessun errore. Quando il denominatore è nullo, la metrica risulta indefinita e la convenzione di rappresentazione deve essere dichiarata.''',formula=r'\mathrm{Prec}=\frac{TP}{TP+FP},\qquad\mathrm{Rec}=\frac{TP}{TP+FN}',tikz=d('D09',rect(.6,.8,6.8,2.5)+n(3.7,1.65,r'Positivi previsti: $TP+FP$',w=6)+rect(.6,3.5,6.8,5.2,'Quantum')+n(3.7,4.35,r'Positivi osservati: $TP+FN$',w=6)),richiamo='La classe positiva e il denominatore determinano il significato della metrica.',origine='M16:81–85')
p('Sbilanciamento e media dei richiami',
'''In un campione artificiale con novanta casi A e dieci casi B, la previsione costante A raggiunge accuratezza pari al novanta per cento, pur lasciando tutti i casi B senza riconoscimento. Il richiamo vale uno per A e zero per B, per cui la loro media è un mezzo. La balanced accuracy assegna uguale peso ai richiami delle classi e rende evidente questo limite. La scelta delle metriche deve comunque riflettere costi, prevalenze e finalità dell’applicazione, conservando i conteggi necessari a interpretarle.''',formula=r'BA=\frac1K\sum_{c=1}^{K}\frac{TP_c}{TP_c+FN_c}',figura='M16/F11',didascalia='Esempio distinto dal dataset litologico: novanta A, dieci B e previsione costante A.',richiamo='Una metrica aggregata deve essere accompagnata dalle prestazioni delle classi rilevanti.',origine='M16:76–80')
p('Regressione logistica per una risposta binaria',
'''La domanda binaria distingue Basalto dalle altre due classi e usa soltanto la densità standardizzata. Il modello esprime il logaritmo del rapporto fra probabilità positiva e negativa come funzione lineare del predittore, mentre la trasformazione logistica mantiene la probabilità fra zero e uno. La curva viene stimata sui campioni di addestramento e applicata al test. La probabilità rappresenta una previsione condizionata ai dati e al modello, la cui calibrazione richiede una verifica distinta dalla semplice separazione delle classi.''',formula=r'\log\frac{p(z)}{1-p(z)}=\beta_0+\beta_1z,\qquad p(z)=\frac1{1+e^{-(\beta_0+\beta_1z)}}',figura='M16/F06',didascalia='Curva stimata sulla densità. I cerchi mostrano le risposte binarie del test; i valori verticali sono zero oppure uno.',richiamo='Una probabilità predetta deve essere interpretata rispetto alla specificazione e al dominio del modello.',origine='M16:41–45')
p('Soglia e conseguenze della decisione',
'''Trasformare una probabilità in una classe richiede una soglia. Nel test, le soglie 0,2, 0,5 e 0,8 producono rispettivamente quattordici, dieci e sette positivi, perché gli insiemi selezionati si restringono all’aumentare del criterio. In una decisione con costi positivi costanti, probabilità calibrate e costo nullo delle classificazioni corrette, il confronto fra perdita attesa positiva e negativa determina una soglia teorica. La scelta operativa richiede che tali ipotesi e i costi siano pertinenti all’applicazione.''',formula=r'\widehat y=\mathbf1\{p\geq t\},\qquad t=\frac{C_{FP}}{C_{FP}+C_{FN}}',figura='M16/F07',didascalia='Tre soglie illustrative sulla stessa probabilità logistica. Il confronto serve a leggere la regola, senza selezionarla sul test.',richiamo='La soglia collega probabilità e conseguenze delle decisioni entro ipotesi esplicite.',origine='M16:86–90; approfondimento R5')
p('Il punteggio di Brier valuta le probabilità',
'''Il punteggio di Brier è la media degli scarti quadratici fra probabilità prevista e risposta binaria. Penalizza previsioni confidenti che risultano errate e utilizza l’intera scala probabilistica, mentre l’accuratezza dipende da una soglia. Per la logistica del laboratorio vale circa 0,04286 sui trenta campioni di test. Il valore va confrontato con riferimenti pertinenti alla stessa popolazione e prevalenza; da solo non descrive quali classi o intervalli di probabilità contribuiscano maggiormente all’errore.''',formula=r'BS=\frac1n\sum_{i=1}^{n}(p_i-y_i)^2,\qquad 0\leq BS\leq1',destra='Una previsione perfetta assegna probabilità uno ai positivi e zero ai negativi, ottenendo punteggio nullo. Una previsione costante pari alla prevalenza osservata produce un riferimento dipendente dalla composizione del campione. Nel progetto applicato, il riferimento probabilistico deve essere definito senza utilizzare le etichette del test per adattarlo.',richiamo='Un punteggio probabilistico richiede riferimenti e condizioni di confronto dichiarati.',origine='M16:91–95')
c=estratto('M16','brier',"d <- read.csv('dati/ml_v3.csv')\ntr <- d$split=='train'\nmu <- mean(d$densita[tr]); s <- sd(d$densita[tr])\nz <- (d$densita-mu)/s\ny <- as.integer(d$litologia=='Basalto')\nf <- glm(y~z,data=data.frame(y=y[tr],z=z[tr]),\n family=binomial())\np <- predict(f,data.frame(z=z[!tr]),\n type='response')\nbs <- mean((p-y[!tr])^2)\nstopifnot(abs(bs-0.04285672213432)<1e-10)\nbs")
p('Dal modello alle probabilità verificabili',
'''Il frammento ricostruisce la trasformazione della densità, adatta la risposta binaria sull’addestramento e calcola il punteggio sui campioni esclusi. La tolleranza verifica la concordanza con il valore atteso dell’esercizio, mantenendo distinto il controllo numerico dall’incertezza della prestazione. Per una nuova applicazione si conserverebbero coefficienti, media e deviazione standard del predittore, insieme alla definizione della classe positiva e alle condizioni nelle quali le misure sono disponibili.''',codice=c,richiamo='Il controllo numerico rende verificabile il calcolo senza attribuire precisione aggiuntiva alla valutazione predittiva.',origine='M16:41–45,91–95')
p('Calibrazione e numerosità degli intervalli',
'''Le probabilità vengono suddivise in tre intervalli, entro i quali si confrontano probabilità media e frequenza osservata di Basalto. I gruppi contengono rispettivamente diciassette, cinque e otto campioni, per cui soprattutto il punto centrale può variare molto al cambiare di poche osservazioni. La diagonale rappresenta la corrispondenza ideale nel riassunto per intervalli. Questa rappresentazione descrittiva usa soltanto tre stazioni di test e richiede dati ulteriori per valutare stabilmente la calibrazione in un contesto di applicazione.''',figura='M16/F08',didascalia='Intervalli delimitati da 1/3 e 2/3. Le etichette riportano il numero di casi che sostiene ciascun punto.',richiamo='La lettura della calibrazione dipende dalla numerosità e dalla struttura delle osservazioni in ogni intervallo.',origine='M16:91–95')
m.sezione_nuova('Diagnostica e trasferibilità')
p('Permutare un predittore per esaminare il modello',
'''L’importanza per permutazione confronta la prestazione originaria con quella ottenuta rimescolando un predittore, mantenendo fisso il classificatore. La revisione ripete trenta permutazioni per variabile, mostrando la variabilità del calo di accuratezza. La procedura rompe associazioni fra predittori e può generare combinazioni lontane dal dominio dei dati, specialmente in presenza di correlazioni. Il risultato riguarda la sensibilità di questo modello e di questo campione; il laboratorio lo utilizza come diagnosi illustrativa, senza tornare a selezionare variabili sul test.''',formula=r'I_j=Acc_{base}-Acc_{perm(j)}',figura='M16/F10',didascalia='Trenta permutazioni per predittore, classificatore del centroide fisso. I box riassumono i cali osservati.',richiamo='L’importanza predittiva dipende da modello, dati e perturbazione applicata; la sua interpretazione causale richiede altro.',origine='M16:96–100')
p('Informazione della risposta nascosta nei predittori',
'''Una variabile che codifica direttamente la classe consente una previsione perfetta perché trasferisce la risposta nel problema predittivo. Il controesempio rende evidente una contaminazione che, nelle applicazioni, può essere meno riconoscibile: identificativi costruiti dalle etichette, misure disponibili soltanto dopo la diagnosi o sintesi calcolate utilizzando anche i dati esclusi. Il controllo della disponibilità temporale e della provenienza di ogni predittore precede l’adattamento, poiché una buona metrica può convivere con una domanda predittiva formulata in modo circolare.''',tikz=d('D10',rect(.6,.6,6.8,1.8)+n(3.7,1.2,r'Classe osservata $Y$',w=6)+a(3.7,2,3.7,2.7,'Measure')+rect(.6,2.9,6.8,4.1,'Measure')+n(3.7,3.5,r'Predittore costruito da $Y$',w=6)+a(3.7,4.3,3.7,4.9,'Measure')+n(3.7,5.5,'Accuratezza perfetta per costruzione',w=6.7,size=11.5)),richiamo='Ogni predittore deve essere disponibile nel momento e nelle condizioni in cui la previsione verrà richiesta.',origine='M16:101–105')
p('Scheda del modello e limiti dell’esperimento',
'''La scheda finale riporta classi, predittori, unità, trasformazioni, algoritmo, regole di selezione, unità di validazione e conteggi delle prestazioni. Il centroide del laboratorio utilizza cinque variabili standardizzate e viene valutato su tre stazioni sintetiche, con accuratezza uno sui trenta provini. La forte separazione delle classi limita il confronto fra metodi, mentre il riuso didattico del test impedisce di presentare l’intero percorso come una selezione seguita da un’unica verifica indipendente. Il trasferimento a dati reali richiede campioni e protocolli ulteriori.''',destra='I laboratori N01–N05 costruiscono dati, separazione e centroide; N06–N12 confrontano vicini, logistica, alberi e validazione; N13–N17 sviluppano metriche e probabilità; N18–N20 completano diagnostica, contaminazione e scheda. L’esercizio conclusivo definisca un nuovo protocollo prima di generare ulteriori stazioni di prova.',richiamo='La scheda del modello deve rendere ricostruibili sia la previsione sia l’evidenza che ne sostiene l’impiego.',origine='M16:106–110')
m.salva()
